import Foundation
struct AlertRuntimeState: Codable, Sendable, Equatable { var active = false; var lastFiredAt: Date?; var acknowledgedAt: Date? }
struct AlertEvaluation: Sendable { let states: [UUID: AlertRuntimeState]; let events: [InfrastructureEvent] }
enum AlertEngine {
    static func evaluate(rules:[AlertRule],conditions:[AlertRuleKind:Bool],previous:[UUID:AlertRuntimeState],now:Date=Date())->AlertEvaluation { var states=previous; var events:[InfrastructureEvent]=[]; for rule in rules where rule.enabled { var state=states[rule.id] ?? AlertRuntimeState(); let triggered=conditions[rule.kind] ?? false; if triggered && !state.active { let muted=rule.muteUntil.map{$0>now} ?? false; let cooled=state.lastFiredAt.map{now.timeIntervalSince($0)>=rule.cooldown} ?? true; state.active=true; if !muted && cooled { events.append(event(rule,now,false)); state.lastFiredAt=now; state.acknowledgedAt=nil } } else if !triggered && state.active { state.active=false; state.acknowledgedAt=nil; events.append(event(rule,now,true)) }; states[rule.id]=state }; return AlertEvaluation(states:states,events:events) }
    private static func event(_ rule:AlertRule,_ date:Date,_ recovery:Bool)->InfrastructureEvent { InfrastructureEvent(id:UUID(),nodeID:rule.nodeID,timestamp:date,componentID:"alert:\(rule.kind.rawValue)",kind:"alert",title:recovery ? "Recovered: \(rule.kind.rawValue)" : "Alert: \(rule.kind.rawValue)",detail:recovery ? "The observed condition cleared." : "The configured local rule is active.",state:recovery ? .online : rule.severity == .critical ? .critical : .warning,isRecovery:recovery) }
}
